() => { const p = Array.from(document.querySelectorAll('app-home p.nombreModulos')).find(x=>x.textContent.trim()==='Vendedores');
            if(!p) return 'NO-TILE'; const a = p.closest('a'); if(!a) return 'NO-ANCHOR';
            a.dispatchEvent(new MouseEvent('click',{bubbles:true,cancelable:true,view:window})); return 'CLICKED'; }

() => { const grp=document.querySelector('app-vendedores ion-accordion-group');
            const acc=document.querySelector('app-vendedores ion-accordion');
            if(!grp||!acc) return 'NO-ACC';
            grp.value=acc.value;
            grp.dispatchEvent(new CustomEvent('ionChange',{detail:{value:acc.value},bubbles:true}));
            return 'SET:'+acc.value; }

